The following code is a simple context manager that acquires three resources in order. If any of the middle steps fail, the resources acquired so far are released in reverse order.
import contextlib
class ThreeResources:
    def __init__(self):
        self.r1 = None
        self.r2 = None
        self.r3 = None
    def __enter__(self):
        try:
            self.r1 = Resource('r1')
            self.r2 = Resource('r2')
            self.r3 = Resource('r3')
        except:
            self.__exit__(None, None, None)
            raise
        return self.r1, self.r2, self.r3
    def __exit__(self, exc_type, exc_value, traceback):
        if self.r3 is not None:
            self.r3.release()
        if self.r2 is not None:
            self.r2.release()
        if self.r1 is not None:
            self.r1.release()
with ThreeResources() as (r1, r2, r3):
    print(r1, r2, r3)
